class Vector {
    int x, y;
public:
    Vector(int a, int b) : x(a), y(b) {}

    // Binary Operator (Member Function)
    Vector operator+(const Vector& other) const {
        return Vector(x + other.x, y + other.y);
    }
    // Usage: V3 = V1 + V2;
};

class Negatable {
    int val;
public:
    Negatable(int v) : val(v) {}

    // Unary Operator (Member Function)
    Negatable operator-() const {
        return Negatable(-val);
    }
    // Usage: N_neg = -N1;
};

// Stream Insertion (Non-Member/Friend Function)
class Data {
    int value;
public:
    Data(int v) : value(v) {}

    friend std::ostream& operator<<(std::ostream& os, const Data& d) {
        os << "Data{" << d.value << "}";
        return os;
    }
    // Usage: std::cout << d_obj;
};

class ArrayWrap {
    int data[10];
public:
    // Subscript Operator (Read/Write)
    int& operator[](size_t index) {
        return data[index];
    }
    // Subscript Operator (Read-Only)
    const int& operator[](size_t index) const {
        return data[index];
    }
    // Usage: aw[0] = 42;
};
